322	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
323	        ownerPageDto.setPage(ownerPage.getNumber());
324	        ownerPageDto.setSize(ownerPage.getSize());
325	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
326	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
327	        return ownerPageDto;
328	    }
